#[derive(Default, PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct Window {
    pub fun: Function,
    pub order_by: Option<Vec<OrderBy>>,
    pub partition: Option<Vec<Expr>>,
}

impl Window {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsWindow<'a>> {
        use crate::types::generated::query_generated::WindowBuilder as FbsWindowBuilder;

        let fun_offset = self.fun.serialize_to(builder);
        let order_by_offset = self.order_by.as_ref().map(|v| {
            let mut order_by_offsets = Vec::with_capacity(v.len());
            for val in v.iter() {
                let offset = val.serialize_to(builder);
                order_by_offsets.push(offset);
            }
            let order_by_offset = builder.create_vector(&order_by_offsets);
            order_by_offset
        });
        let partition_offset = self.partition.as_ref().map(|v| {
            let mut partition_offsets = Vec::with_capacity(v.len());
            for val in v.iter() {
                let offset = val.serialize_to(builder);
                partition_offsets.push(offset);
            }
            let partition_offset = builder.create_vector(&partition_offsets);
            partition_offset
        });

        let mut bldr = FbsWindowBuilder::new(builder);
        bldr.add_fun(fun_offset);
        if let Some(offset) = order_by_offset {
            bldr.add_order_by(offset);
        }
        if let Some(offset) = partition_offset {
            bldr.add_partition(offset);
        }
        bldr.finish()
    }
}

impl From<FbsWindow<'_>> for Window {
    fn from(fbs: FbsWindow<'_>) -> Self {
        let fun = Function::from(fbs.fun());
        let order_by = if let Some(val) = fbs.order_by() {
            let mut order_by = Vec::new();
            for elem in val {
                order_by.push(elem.into());
            }

            Some(order_by)
        } else {
            None
        };

        let partition = if let Some(val) = fbs.partition() {
            let mut partition = Vec::new();
            for elem in val {
                partition.push(elem.into());
            }

            Some(partition)
        } else {
            None
        };

        Self {
            fun,
            order_by,
            partition,
        }
    }
}

