#[derive(Default, PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct Query {
    pub bound_sources: Option<Vec<TableSourceInstance>>,
    pub explain: Option<Explain>,
    pub limit: u32,
    pub query: QueryElement,
    pub values: Option<Vec<ValueInstance>>,
}

impl Query {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsQuery<'a>> {
        use crate::types::generated::query_generated::QueryBuilder as FbsQueryBuilder;

        let bound_sources_offset = self.bound_sources.as_ref().map(|v| {
            let mut bound_sources_offsets = Vec::with_capacity(v.len());
            for val in v.iter() {
                let offset = val.serialize_to(builder);
                bound_sources_offsets.push(offset);
            }
            let bound_sources_offset = builder.create_vector(&bound_sources_offsets);
            bound_sources_offset
        });
        let explain_offset = self.explain.as_ref().map(|o| o.serialize_to(builder));
        let query_offset = self.query.serialize_to(builder);
        let values_offset = self.values.as_ref().map(|v| {
            let mut values_offsets = Vec::with_capacity(v.len());
            for val in v.iter() {
                let offset = val.serialize_to(builder);
                values_offsets.push(offset);
            }
            let values_offset = builder.create_vector(&values_offsets);
            values_offset
        });

        let mut bldr = FbsQueryBuilder::new(builder);
        if let Some(offset) = bound_sources_offset {
            bldr.add_bound_sources(offset);
        }
        if let Some(offset) = explain_offset {
            bldr.add_explain(offset);
        }
        bldr.add_limit(self.limit);
        bldr.add_query(query_offset);
        if let Some(offset) = values_offset {
            bldr.add_values(offset);
        }
        bldr.finish()
    }
}

impl From<FbsQuery<'_>> for Query {
    fn from(fbs: FbsQuery<'_>) -> Self {
        let bound_sources = if let Some(val) = fbs.bound_sources() {
            let mut bound_sources = Vec::new();
            for elem in val {
                bound_sources.push(elem.into());
            }

            Some(bound_sources)
        } else {
            None
        };

        let explain = fbs.explain().map(Explain::from);
        let limit = fbs.limit();
        let query = QueryElement::from(fbs.query());
        let values = if let Some(val) = fbs.values() {
            let mut values = Vec::new();
            for elem in val {
                values.push(elem.into());
            }

            Some(values)
        } else {
            None
        };

        Self {
            bound_sources,
            explain,
            limit,
            query,
            values,
        }
    }
}

