#[derive(Default, PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct ValueRow {
    pub row: Vec<Expr>,
}

impl ValueRow {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsValueRow<'a>> {
        use crate::types::generated::query_generated::ValueRowBuilder as FbsValueRowBuilder;

        let mut row_offsets = Vec::with_capacity(self.row.len());
        for val in self.row.iter() {
            let offset = val.serialize_to(builder);
            row_offsets.push(offset);
        }
        let row_offset = builder.create_vector(&row_offsets);

        let mut bldr = FbsValueRowBuilder::new(builder);
        bldr.add_row(row_offset);
        bldr.finish()
    }
}

impl From<FbsValueRow<'_>> for ValueRow {
    fn from(fbs: FbsValueRow<'_>) -> Self {
        let mut row = Vec::new();
        for elem in fbs.row() {
            row.push(elem.into());
        }

        Self { row }
    }
}

