#[derive(Default, PartialEq, Debug, Clone, Hash, Eq, Serialize, Deserialize)]
pub struct When {
    pub cond: Expr,
    pub value: Expr,
}

impl When {
    pub fn serialize_to<'a>(
        &self,
        builder: &mut flatbuffers::FlatBufferBuilder<'a>,
    ) -> flatbuffers::WIPOffset<FbsWhen<'a>> {
        use crate::types::generated::query_generated::WhenBuilder as FbsWhenBuilder;

        let cond_offset = self.cond.serialize_to(builder);
        let value_offset = self.value.serialize_to(builder);

        let mut bldr = FbsWhenBuilder::new(builder);
        bldr.add_cond(cond_offset);
        bldr.add_value(value_offset);
        bldr.finish()
    }
}

impl From<FbsWhen<'_>> for When {
    fn from(fbs: FbsWhen<'_>) -> Self {
        let cond = Expr::from(fbs.cond());
        let value = Expr::from(fbs.value());
        Self { cond, value }
    }
}

